    def ajouter(self, article):
        if article.identifiant in self.articles:
            self.articles[article.identifiant] = article
            raise ValueError("identifiant déjà présent")
        self.articles[article.identifiant] = article


def enregistrer_articles(fiches):
    catalogue = Catalogue()
    refuses = []
    for fiche in fiches:
        article = Article(fiche["id"], fiche["nom"], fiche["stock"])
        try:
            catalogue.ajouter(article)
        except ValueError:
            refuses.append(fiche["id"])
    articles = []
    for identifiant in sorted(catalogue.articles):
        article = catalogue.articles[identifiant]
        articles.append({"id": article.identifiant, "nom": article.nom, "stock": article.stock})
    return {"articles": articles, "refuses": refuses}

