def verifier_quantite(quantite):
    if type(quantite) is not int:
        raise TypeError("quantité : entier attendu")
    if quantite < 0:
        raise ValueError("quantité négative")
    return quantite


class Article:

    def __init__(self, identifiant, nom, stock):
        stock = verifier_quantite(stock)
        self.identifiant = identifiant
        self.nom = nom
        self.stock = stock

    def retirer(self, quantite):
        quantite = verifier_quantite(quantite)
        if quantite > self.stock:
            raise ValueError("stock insuffisant")
        self.stock -= quantite


class Catalogue:

    def __init__(self):
        self.articles = {}

    def ajouter(self, article):
        if article.identifiant in self.articles:
            raise ValueError("identifiant déjà présent")
        self.articles[article.identifiant] = article

    def chercher(self, identifiant):
        if identifiant not in self.articles:
            raise KeyError("identifiant absent")
        return self.articles[identifiant]

    def retirer(self, identifiant, quantite):
        article = self.chercher(identifiant)
        article.retirer(quantite)


def piloter_catalogue(fiches, demandes):
    catalogue = Catalogue()
    for fiche in fiches:
        article = Article(fiche["id"], fiche["nom"], fiche["stock"])
        catalogue.ajouter(article)
    erreurs = []
    for numero, demande in enumerate(demandes, start=1):
        try:
            catalogue.retirer(demande["id"], demande["quantite"])
        except KeyError:
            erreurs.append({"ligne": numero, "id": demande["id"], "motif": "article absent"})
        except (TypeError, ValueError) as erreur:
            erreurs.append({"ligne": numero, "id": demande["id"], "motif": str(erreur)})
    articles = []
    for identifiant in sorted(catalogue.articles):
        article = catalogue.chercher(identifiant)
        articles.append({"id": article.identifiant, "nom": article.nom, "stock": article.stock})
    return {"articles": articles, "erreurs": erreurs}

